private Task? _shutdownTask;

public Task ShutdownAsync()
{
    return _shutdownTask ??= ShutdownCoreAsync();
}

private async Task ShutdownCoreAsync()
{
    var stops = Services.GetServices<IExtensionService>()
        .Select(service => service.SignalStopAsync());
    await Task.WhenAll(stops).WaitAsync(ShutdownTimeout);
    Dispose();
    AppWindow?.Close();
}

internal async void MainWindow_Closed(object sender, WindowEventArgs args)
{
    if (_closeStarted)
    {
        return;
    }

    _closeStarted = true;
    PersistWindowPosition();
    DisposeUiResources();
    await App.Current.ShutdownAsync();
}

public async Task SignalStopAsync()
{
    var extensions = await GetInstalledExtensionsAsync().ConfigureAwait(false);
    await Task.WhenAll(
        extensions.Select(extension => extension.SignalStopAsync()));
}
